const S300 = RAW.series.hs300;
const S688 = RAW.series.kc50;
const DATES = S300.dates;
const UP = '#d64545';
const DOWN = '#2e9e6b';

function klineData(s) {
  const out = [];
  for (let i = 0; i < DATES.length; i++) {
    out.push([s.open[i], s.close[i], s.low[i], s.high[i]]);
  }
  return out;
}

function baseAxis() {
  return {
    tooltip: { trigger: 'axis' },
    grid: { left: 60, right: 18, top: 30, bottom: 26 },
    xAxis: { type: 'category', data: DATES, axisLabel: { fontSize: 10, color: '#6b7280' } },
    yAxis: { type: 'value', scale: true, axisLabel: { fontSize: 10, color: '#6b7280' } }
  };
}

function initKline(id, s, name) {
  const opt = baseAxis();
  opt.legend = { data: [name + ' 日K', 'MA20', 'MA60', '布林上轨', '布林下轨'], top: 0, textStyle: { fontSize: 11, color: '#374151' } };
  opt.series = [
    { name: name + ' 日K', type: 'candlestick', data: klineData(s),
      itemStyle: { color: UP, color0: DOWN, borderColor: UP, borderColor0: DOWN } },
    { name: 'MA20', type: 'line', data: s.ma20, showSymbol: false, lineStyle: { width: 1.2, color: '#b45309' } },
    { name: 'MA60', type: 'line', data: s.ma60, showSymbol: false, lineStyle: { width: 1.2, color: '#534ab7' } },
    { name: '布林上轨', type: 'line', data: s.bb_up, showSymbol: false, lineStyle: { width: 1, type: 'dashed', color: '#9ca3af' } },
    { name: '布林下轨', type: 'line', data: s.bb_low, showSymbol: false, lineStyle: { width: 1, type: 'dashed', color: '#9ca3af' } }
  ];
  echarts.init(document.getElementById(id)).setOption(opt);
}

function initMacd(id, s) {
  const opt = baseAxis();
  opt.legend = { data: ['MACD柱', 'DIF', 'DEA'], top: 0, textStyle: { fontSize: 11, color: '#374151' } };
  const bars = s.macd.map(function (v) {
    return { value: v, itemStyle: { color: v >= 0 ? UP : DOWN } };
  });
  opt.series = [
    { name: 'MACD柱', type: 'bar', data: bars, barWidth: 2 },
    { name: 'DIF', type: 'line', data: s.dif, showSymbol: false, lineStyle: { width: 1.4, color: '#1f2937' } },
    { name: 'DEA', type: 'line', data: s.dea, showSymbol: false, lineStyle: { width: 1.4, color: '#b45309' } }
  ];
  echarts.init(document.getElementById(id)).setOption(opt);
}

function initRsi(id) {
  const opt = baseAxis();
  opt.legend = { data: ['300 RSI6', '688 RSI6', '300 RSI12', '688 RSI12'], top: 0, textStyle: { fontSize: 11, color: '#374151' } };
  opt.yAxis = { type: 'value', min: 0, max: 100, axisLabel: { fontSize: 10, color: '#6b7280' } };
  opt.series = [
    { name: '300 RSI6', type: 'line', data: S300.rsi6, showSymbol: false, lineStyle: { width: 1.2, color: '#185fa5' },
      markLine: { silent: true, symbol: 'none', lineStyle: { color: '#9ca3af', type: 'dashed' }, label: { fontSize: 10, color: '#6b7280' }, data: [{ yAxis: 70 }, { yAxis: 30 }] } },
    { name: '688 RSI6', type: 'line', data: S688.rsi6, showSymbol: false, lineStyle: { width: 1.2, color: '#c2410c' } },
    { name: '300 RSI12', type: 'line', data: S300.rsi12, showSymbol: false, lineStyle: { width: 1.2, type: 'dashed', color: '#185fa5' } },
    { name: '688 RSI12', type: 'line', data: S688.rsi12, showSymbol: false, lineStyle: { width: 1.2, type: 'dashed', color: '#c2410c' } }
  ];
  echarts.init(document.getElementById(id)).setOption(opt);
}

function initKdj(id) {
  const opt = baseAxis();
  opt.legend = { data: ['300 K', '300 D', '688 K', '688 D'], top: 0, textStyle: { fontSize: 11, color: '#374151' } };
  opt.series = [
    { name: '300 K', type: 'line', data: S300.kdj_k, showSymbol: false, lineStyle: { width: 1.2, color: '#185fa5' },
      markLine: { silent: true, symbol: 'none', lineStyle: { color: '#9ca3af', type: 'dashed' }, label: { fontSize: 10, color: '#6b7280' }, data: [{ yAxis: 80 }, { yAxis: 20 }] } },
    { name: '300 D', type: 'line', data: S300.kdj_d, showSymbol: false, lineStyle: { width: 1.2, type: 'dashed', color: '#185fa5' } },
    { name: '688 K', type: 'line', data: S688.kdj_k, showSymbol: false, lineStyle: { width: 1.2, color: '#c2410c' } },
    { name: '688 D', type: 'line', data: S688.kdj_d, showSymbol: false, lineStyle: { width: 1.2, type: 'dashed', color: '#c2410c' } }
  ];
  echarts.init(document.getElementById(id)).setOption(opt);
}

const normChart = echarts.init(document.getElementById('chart1'));
normChart.setOption({
  tooltip: { trigger: 'axis' },
  legend: { data: ['沪深300', '科创50'], top: 0, textStyle: { fontSize: 11, color: '#374151' } },
  grid: { left: 52, right: 18, top: 30, bottom: 26 },
  xAxis: { type: 'category', data: DATES, axisLabel: { fontSize: 10, color: '#6b7280' } },
  yAxis: { type: 'value', scale: true, name: '基点=100', nameTextStyle: { fontSize: 10, color: '#6b7280' }, axisLabel: { fontSize: 10, color: '#6b7280' } },
  series: [
    { name: '沪深300', type: 'line', data: S300.norm, showSymbol: false, lineStyle: { width: 1.6, color: '#185fa5' }, areaStyle: { opacity: 0.06 } },
    { name: '科创50', type: 'line', data: S688.norm, showSymbol: false, lineStyle: { width: 1.6, color: '#c2410c' } }
  ]
});

function showView(v) {
  document.getElementById('view-chart').style.display = v === 'chart' ? 'block' : 'none';
  document.getElementById('view-table').style.display = v === 'table' ? 'block' : 'none';
  document.getElementById('btn-chart').className = v === 'chart' ? 'seg active' : 'seg';
  document.getElementById('btn-table').className = v === 'table' ? 'seg active' : 'seg';
  if (v === 'chart') { normChart.resize(); }
}

initKline('chart2', S300, '沪深300');
initKline('chart3', S688, '科创50');
initMacd('chart4', S300);
initMacd('chart5', S688);
initRsi('chart6');
initKdj('chart7');

window.addEventListener('resize', function () {
  const ids = ['chart1', 'chart2', 'chart3', 'chart4', 'chart5', 'chart6', 'chart7'];
  for (let i = 0; i < ids.length; i++) {
    const inst = echarts.getInstanceByDom(document.getElementById(ids[i]));
    if (inst) { inst.resize(); }
  }
});
